extern SPI_HandleTypeDef hspi1;

static SPI_HandleTypeDef *const spi_map[MCAL_SPI_COUNT] = {
    [MCAL_SPI_1] = &hspi1,
};

/*************** Section 3 : Software Interfaces Definitions (APIs) ****************/

Std_ReturnType Mcal_Spi_Transmit(Mcal_SpiId_t id, const uint8_t *data,
                                 uint16_t len, uint32_t timeout_ms)
{
    if ((unsigned)id >= (unsigned)MCAL_SPI_COUNT || data == NULL || len == 0U) return E_NOT_OK;

    return (HAL_SPI_Transmit(spi_map[id], (uint8_t *)data, len, timeout_ms) == HAL_OK)
           ? E_OK : E_NOT_OK;
}

Std_ReturnType Mcal_Spi_Receive(Mcal_SpiId_t id, uint8_t *data,
                                uint16_t len, uint32_t timeout_ms)
{
    if ((unsigned)id >= (unsigned)MCAL_SPI_COUNT || data == NULL || len == 0U) return E_NOT_OK;

    return (HAL_SPI_Receive(spi_map[id], data, len, timeout_ms) == HAL_OK)
           ? E_OK : E_NOT_OK;
}
